(self.webpackChunkvuepress_blog=self.webpackChunkvuepress_blog||[]).push([[6786],{9608:(e,l,a)=>{"use strict";a.r(l),a.d(l,{data:()=>t});const t={key:"v-85b7c010",path:"/pages/self-daily/daily-log/2025-12-16/",title:"",lang:"zh-CN",frontmatter:{sidebar:!1},excerpt:"",headers:[{level:3,title:"对于逝世的一些思考",slug:"对于逝世的一些思考",children:[]}],filePathRelative:"pages/self-daily/daily-log/2025-12-16/README.md",git:{updatedTime:176595886e4,contributors:[{name:"COOKIES-LGL",email:"1344714332@qq.com",commits:1}]}}},4137:(e,l,a)=>{"use strict";a.r(l),a.d(l,{default:()=>i});var t=a(6252);const s=(0,t.Wm)("h3",{id:"对于逝世的一些思考"},[(0,t.Wm)("a",{class:"header-anchor",href:"#对于逝世的一些思考"},"#"),(0,t.Uk)(" 对于逝世的一些思考")],-1),r=(0,t.Wm)("p",null,"   昨天母亲发来了微信，昨天凌晨 2 点多，大伯母去世了，大姆母身体一直不好，最近一两年更是严重，去年过年还是在医院躺着，上周就听闻我妈说，我大堂哥都回去了，医院让送回家待着已经进不了食了。从记事起，已经两位亲人离世了，大姑姑是在 22 年的时候离开了，大姑姑是由于在工地工作不小心受了工伤，导致不能正常行走，基本在轮椅上待了十几年。往些年也只是过年回去看望她，她也常常每年正月初五站在她家门口等我们这些娘家人去看望她。现在大伯母也走了，大伯母在我们这个大家庭像是一位大家长一样，父亲九兄妹，我爸排老八，爷爷、奶奶去世得早，长兄如父，大伯母自然扮演了相当部分大家长的角色。小时候去大伯父家，最期待的就是伯母的厨艺了，饭做得太香了。伯父伯母生活非常节俭，那个年代的人应该很多都是舍不得吃舍不得穿的。两口子作为七八十年代的知识分子，送了两个娃去上大学，读研。也是非常厉害的。不知不觉父母那辈的人都年纪大了，大伯马上八十了我父亲也快六十了。可以预见的是，随着时间的推移，未来会有亲人不断离开。人生一辈子想来也挺简单，真应该珍惜和家人的每一天。时间是不均匀的，想起生活的点滴，在时间面前显得多么苍白无力，那些村里的老人，晒着太阳能坐一天，那些小时候大人说的等一会会，原来真的就是一会会。现在想想人类似乎一直在学习怎么面对死亡，但当死亡真的来临的时候又还是会变得手足无措。很多时候你所追求的财富，权利，名声，往往也经不起时间的拷打，未来并没有想想的那么遥远，一年真的好快，像是开了加速度。",-1),i={render:function(e,l){return(0,t.wg)(),(0,t.j4)(t.HY,null,[s,r],64)}}}}]);